def subtract(a, b):
    # Filter out empty intervals
    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    # Merge overlapping/touching intervals in both lists
    def merge_intervals(intervals):
        if not intervals:
            return []

        sorted_intervals = sorted(intervals)
        merged = [sorted_intervals[0]]

        for start, end in sorted_intervals[1:]:
            last_start, last_end = merged[-1]
            if start <= last_end:
                merged[-1] = [last_start, max(last_end, end)]
            else:
                merged.append([start, end])

        return merged

    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    # Subtract b from a
    result = []

    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_ranges = []
            for c_start, c_end in current_ranges:
                if b_end <= c_start or b_start >= c_end:
                    # No overlap
                    new_ranges.append([c_start, c_end])
                else:
                    # There is overlap
                    if c_start < b_start:
                        new_ranges.append([c_start, b_start])
                    if c_end > b_end:
                        new_ranges.append([b_end, c_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Sort and merge touching intervals in result
    result = merge_intervals(result)

    return result

